package org.springframework.samples.petclinic.service;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Business rule: on creation an owner is assigned a {@code customerCode} formatted
 * {@code <LAST3>-<NNNN>}, where LAST3 is the upper-cased first three letters of the last name
 * and NNNN is a global 4-digit zero-padded sequence equal to one more than the current number
 * of owners (e.g. {@code SMI-0007}). Kept as a small, self-contained unit so the rule can be
 * applied from the create flow without adding complexity to the controller or service.
 */
public final class OwnerCustomerCodePolicy {

    private OwnerCustomerCodePolicy() {
    }

    /**
     * Assign the {@code customerCode} for a newly created owner.
     *
     * @param clinicService source of the current owner count
     * @param owner         the owner being created
     */
    public static void assignCustomerCode(ClinicService clinicService, Owner owner) {
        String lastName = owner.getLastName();
        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        int sequence = clinicService.findAllOwners().size() + 1;
        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
    }
}
package org.springframework.samples.petclinic.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: two owners must not share a household by accident. On creation an owner is
 * rejected when another owner already has the same last name and address, compared
 * case-insensitively after collapsing runs of whitespace. The caller may opt in to sharing a
 * household ({@code sharesHousehold == true}), which skips the check. Kept as a small,
 * self-contained unit so the rule can be enforced from the create flow without adding
 * complexity to the controller or service.
 */
public final class OwnerHouseholdPolicy {

    private OwnerHouseholdPolicy() {
    }

    /**
     * Reject the given owner if another existing owner has the same last name and address,
     * unless the request explicitly opted in to sharing a household.
     *
     * @param clinicService   source of the existing owners
     * @param owner           the owner being created
     * @param sharesHousehold whether the request opted in to a shared household
     * @throws DuplicateHouseholdException if the household already exists and sharing was not opted in
     */
    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId())
                && lastName.equals(normalize(existing.getLastName()))
                && address.equals(normalize(existing.getAddress()))) {
                if (!Boolean.TRUE.equals(sharesHousehold)) {
                    throw new DuplicateHouseholdException();
                }
                owner.setHouseholdId(householdId(lastName, address));
                return;
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
    private static String householdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Thrown when another owner already shares the same last name and address. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateHouseholdException extends RuntimeException {
    }
}
package org.springframework.samples.petclinic.service;

import org.springframework.http.HttpStatus;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * Business rule: an owner's telephone must be unique across all owners once normalized
 * (non-digit characters removed). Kept as a small, self-contained unit so the rule can be
 * enforced from the create flow without adding complexity to the controller or service.
 *
 * @author Vitaliy Fedoriv
 */
public final class OwnerTelephonePolicy {

    private OwnerTelephonePolicy() {
    }

    /**
     * Reject the given owner if its normalized telephone matches any other existing owner.
     *
     * @param clinicService source of the existing owners
     * @param owner         the owner being created
     * @throws DuplicateTelephoneException if the normalized telephone is already in use
     */
    public static void rejectDuplicateTelephone(ClinicService clinicService, Owner owner) {
        String normalized = normalize(owner.getTelephone());
        if (normalized.isEmpty()) {
            return;
        }
        for (Owner existing : clinicService.findAllOwners()) {
            if (!existing.getId().equals(owner.getId()) && normalized.equals(normalize(existing.getTelephone()))) {
                throw new DuplicateTelephoneException();
            }
        }
    }

    private static String normalize(String telephone) {
        return telephone == null ? "" : telephone.replaceAll("\\D", "");
    }

    /** Thrown when an owner's normalized telephone is already used by another owner. */
    @ResponseStatus(HttpStatus.CONFLICT)
    public static class DuplicateTelephoneException extends RuntimeException {
    }
}

